{
 "title": "Allow Exceptions in Microsoft Defender Firewall via Registry - DoNotAllowExceptions Set to 0",
 "description": "Detects when the DoNotAllowExceptions registry value is set to 0 (DWORD 0x00000000), which re-enables application\n  and port exceptions in Microsoft Defender Firewall, potentially impairing defense.",
 "tags": [
  "attack.defense-impairment",
  "attack.t1686.003"
 ],
 "logsource_category": "registry_set",
 "groups": [
  {
   "name": "selection_registry",
   "fields": [
    {
     "field": "TargetObject|endswith",
     "modifier": "endswith",
     "values": [
      "\\\\DoNotAllowExceptions"
     ]
    },
    {
     "field": "Details|contains",
     "modifier": "contains",
     "values": [
      "0x00000000"
     ]
    }
   ]
  },
  {
   "name": "condition",
   "fields": []
  }
 ],
 "condition": "selection_registry",
 "falsepositives": [
  "Unknown"
 ],
 "level": "high"
}

{
 "title": "Potential WinAPI Calls Via PowerShell Scripts",
 "description": "Detects PowerShell processes that invoke Windows API functions via Add-Type, DllImport, or direct API calls, which may indicate process injection, token stealing, or other malicious activity.",
 "tags": [
  "attack.execution",
  "attack.t1059.001",
  "attack.t1106",
  "attack.stealth",
  "attack.t1620"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "selection_image",
   "fields": [
    {
     "field": "Image",
     "modifier": "endswith",
     "values": [
      "\\\\powershell.exe",
      "\\\\pwsh.exe"
     ]
    }
   ]
  },
  {
   "name": "selection_scriptblocktext",
   "fields": [
    {
     "field": "ScriptBlockText",
     "modifier": "contains",
     "values": [
      "Add-Type",
      "[DllImport]",
      "kernel32.dll",
      "user32.dll",
      "advapi32.dll",
      "ntdll.dll",
      "VirtualAllocEx",
      "CreateRemoteThread",
      "WriteProcessMemory",
      "OpenProcess",
      "GetProcAddress",
      "LoadLibrary",
      "Marshal.GetDelegateForFunctionPointer",
      "[System.Runtime.InteropServices.Marshal]",
      "-band ",
      "$Win32Constants."
     ]
    }
   ]
  },
  {
   "name": "filter_falsepositive",
   "fields": []
  }
 ],
 "condition": "selection_image and selection_scriptblocktext and not filter_falsepositive",
 "falsepositives": [
  "Legitimate administrative or development scripts that use Add-Type for .NET interop or P/Invoke."
 ],
 "level": "high"
}

{
 "title": "PowerShell Token Obfuscation via Invoke-Obfuscation",
 "description": "Detects TOKEN OBFUSCATION technique from Invoke-Obfuscation by looking for the string Invoke-Obfuscation and its GitHub URL in the command line, or for obfuscated usage involving the format operator (-f) and .Invoke() calls.",
 "tags": [
  "attack.stealth",
  "attack.t1027.009"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "selection_invoke",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "Invoke-Obfuscation"
     ]
    }
   ]
  },
  {
   "name": "selection_github",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "https://github.com/danielbohannon/Invoke-Obfuscation"
     ]
    }
   ]
  },
  {
   "name": "selection_format",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "-f '"
     ]
    }
   ]
  },
  {
   "name": "selection_invoke_method",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      ".Invoke("
     ]
    }
   ]
  },
  {
   "name": "condition",
   "fields": []
  }
 ],
 "condition": "(selection_invoke or selection_github) or (selection_format and selection_invoke_method)",
 "falsepositives": [
  "Legitimate use of Invoke-Obfuscation for testing or training."
 ],
 "level": "high"
}
